<template><div class="work-page"><header class="page-heading"><div><p class="eyebrow">ACCOUNTS</p><h1>账户管理</h1><p class="subtitle">核实当前余额与欠款，和历史消费分开管理。</p></div><RouterLink to="/accounts/new" class="button primary">＋ 新增账户</RouterLink></header><div v-if="error" class="error-box">{{error}}</div><div class="notice">导入的账户未核验前显示“待核实”。信用卡填写当前欠款，其他账户填写可用余额；这不会生成消费记录。</div><div class="two-grid"><section v-for="a in accounts" :key="a.id" class="panel"><div class="panel-head"><h2>{{accountName(a)}}</h2><span class="tag">{{a.currency}}</span></div><div class="panel-body"><p class="metric-label">{{a.type==='credit'?'当前欠款':'当前余额'}}</p><div class="metric-value">{{verified(a.id)?amount(Math.round(a.balance*100),a.currency,show):'待核实'}}</div><p class="subtitle">{{verified(a.id)?'最近核验：'+verified(a.id)?.date:'尚未确认实际余额，不能视为零负债。'}}</p><div class="actions" style="margin-top:20px"><button class="button" @click="start(a)">核验余额</button><RouterLink :to="{path:'/detail',query:{account:a.id,currency:a.currency}}" class="button ghost">查看交易 →</RouterLink></div></div></section></div><section v-if="draft" class="settings-form" style="margin-top:20px"><h2 style="margin-bottom:16px">{{draft.name}} · 核验余额</h2><div class="form-grid"><label class="field">金额（{{draft.currency}}）<input v-model.number="balance" class="control" type="number" step="0.01"/></label><label class="field">核验日期<input v-model="draft.date" class="control" type="date"/></label></div><div class="actions" style="margin-top:16px"><button class="button primary" :disabled="busy" @click="save">保存已核验余额</button><button class="button" @click="draft=null">取消</button></div></section></div></template>
<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {getWorkspace,getSettings,saveSetting,accountName,amount,localDate} from '@/api/workspace'
import type {Account,Setting} from '@/api/workspace'
import {useUserSettingsStore} from '@/stores/userSettings'
const accounts=ref<Account[]>([]),settings=ref<Setting[]>([]),draft=ref<Setting|null>(null),balance=ref(0),busy=ref(false),error=ref(''),user=useUserSettingsStore(),show=computed(()=>user.showAmount)
function verified(id:string){return settings.value.find(s=>s.kind==='balance'&&s.match===id)}
async function load(){try{const [r,s]=await Promise.all([getWorkspace({currency:'CNY',kind:'ledger'}),getSettings()]);accounts.value=r.accounts;settings.value=s}catch(e){error.value=String(e)}}
function start(a:Account){const s=verified(a.id);draft.value=s?{...s,date:localDate()}:{key:'balance:'+a.id,kind:'balance',name:accountName(a),currency:a.currency,cents:0,category:'',match:a.id,date:localDate(),period:'',enabled:true,version:0};balance.value=s?a.balance:0}
async function save(){if(!draft.value)return;busy.value=true;error.value='';try{await saveSetting({...draft.value,cents:Math.round(balance.value*100)});draft.value=null;await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(load)
</script>
